<?php require __DIR__.'/app/bootstrap.php'; nowrd_track_page('page', null);
ensure_taxonomy_schema(); ensure_v8_schema();
$siteName=setting('brand_name',setting('site_name',$config['site_name'] ?? 'NOWRD')); $tagline=setting('brand_tagline',setting('site_tagline','Less noise. More meaning.')); $brandMark=setting('brand_mark','n.');
$search=trim((string)($_GET['q']??'')); $categorySlug=trim((string)($_GET['category']??''));
$pageBlocks=json_decode(setting('page_builder_blocks','[]'),true); if(!is_array($pageBlocks)) $pageBlocks=[]; $pageBlocks=array_slice($pageBlocks,0,8);
$categories=cache_remember('public.categories', nowrd_cache_ttl('cache_ttl_categories', 60), static fn() => $pdo->query("SELECT c.id,c.name,c.slug,(SELECT COUNT(*) FROM post_categories pc JOIN posts p ON p.id=pc.post_id WHERE pc.category_id=c.id AND p.status='published' AND (p.published_at IS NULL OR p.published_at<=NOW())) post_count FROM categories c ORDER BY c.name")->fetchAll());
$sql="SELECT p.*,u.name author_name,(SELECT GROUP_CONCAT(c.name ORDER BY c.name SEPARATOR ', ') FROM post_categories pc JOIN categories c ON c.id=pc.category_id WHERE pc.post_id=p.id) category_names FROM posts p LEFT JOIN users u ON u.id=p.author_id WHERE p.status='published' AND (p.published_at IS NULL OR p.published_at<=NOW())"; $args=[];
if($search!==''){$sql.=' AND (p.title LIKE ? OR p.excerpt LIKE ? OR p.content LIKE ? OR EXISTS (SELECT 1 FROM post_tags pt JOIN tags t ON t.id=pt.tag_id WHERE pt.post_id=p.id AND t.name LIKE ?))';$like='%'.$search.'%';array_push($args,$like,$like,$like,$like);}
if($categorySlug!==''){$sql.=' AND EXISTS (SELECT 1 FROM post_categories pc JOIN categories c ON c.id=pc.category_id WHERE pc.post_id=p.id AND c.slug=?)';$args[]=$categorySlug;}
$sql.=' ORDER BY COALESCE(p.published_at,p.created_at) DESC LIMIT 48';$cacheKey='public.posts.'.hash('sha256', $sql.'|'.json_encode($args));$posts=cache_remember($cacheKey, nowrd_cache_ttl('cache_ttl_posts', 45), static function() use ($pdo,$sql,$args) {$q=$pdo->prepare($sql);$q->execute($args);return $q->fetchAll();});
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="<?=e(setting('site_description', $tagline))?>"><link rel="alternate" type="application/rss+xml" title="<?=e($siteName)?> RSS" href="<?=e(base_url('rss.php'))?>"><link rel="canonical" href="<?=e(base_url('index.php'))?>"><title><?=e($siteName)?> — Journal</title><link rel="stylesheet" href="<?=e(base_url('public/assets/style.css'))?>"><style>.public-search{display:flex;gap:9px;margin:22px 0 14px;max-width:620px}.public-search input{flex:1;min-width:0;border:1px solid var(--line);border-radius:999px;padding:12px 16px;font:inherit;background:#fff}.public-search button{border:0;border-radius:999px;padding:0 18px;background:var(--ink);color:#fff;font-weight:700;cursor:pointer}.public-search>a{align-self:center;color:var(--muted);font-size:12px}.public-categories{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0 26px}.topic-pill{display:inline-flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:12px}.topic-pill.selected{background:var(--accent);border-color:var(--accent);color:var(--ink)}.topic-pill small{opacity:.7}.card-category{font-size:11px;font-weight:750;letter-spacing:.06em;text-transform:uppercase;color:#5b7e34;margin-top:10px}@media(max-width:480px){.public-search{flex-wrap:wrap}.public-search input{flex-basis:100%}.public-search button{padding:11px 16px}}.builder-sections{display:grid;gap:18px;padding-top:24px;padding-bottom:24px}.builder-section{display:grid;grid-template-columns:1fr 1fr;gap:clamp(18px,4vw,48px);align-items:center;border:1px solid var(--line);border-radius:24px;padding:clamp(20px,4vw,44px);background:color-mix(in srgb,var(--paper,#fff) 88%,transparent);overflow:hidden}.builder-section:nth-child(even){grid-template-columns:1fr 1fr}.builder-section:nth-child(even) .builder-section-image{order:2}.builder-section h2{font-size:clamp(25px,4vw,44px);line-height:1.08;letter-spacing:-.04em;margin:0 0 14px}.builder-section p{color:var(--muted);line-height:1.8;white-space:normal}.builder-section-image{width:100%;max-height:380px;object-fit:cover;border-radius:16px;aspect-ratio:4/3}.builder-section-button{display:inline-flex;margin-top:12px;padding:11px 16px;border-radius:999px;background:var(--ink);color:white;font-weight:700;font-size:13px}.builder-cta{background:var(--ink);color:white}.builder-cta p{color:#c4c9d1}.builder-cta .builder-section-button{background:#d5f27b;color:#17200b}.builder-section:not(:has(.builder-section-image)){grid-template-columns:1fr}.builder-section:not(:has(.builder-section-image)) .builder-section-copy{max-width:760px}@media(max-width:650px){.builder-section,.builder-section:nth-child(even){grid-template-columns:1fr;padding:22px}.builder-section:nth-child(even) .builder-section-image{order:0}.builder-section-image{max-height:260px}}</style></head><body><header class="site-header wrap"><a class="brand" href="<?=e(base_url('index.php'))?>"><span class="brand-mark"><?=e($brandMark)?></span> <?=e($siteName)?></a><nav><a href="#latest">Stories</a><a href="#topics">Topics</a><a href="#about">About</a></nav></header><main><section class="hero wrap"><div class="eyebrow"><span class="dot"></span> INDEPENDENT PUBLISHING</div><h1>Ideas worth<br><em>staying for.</em></h1><div class="hero-bottom"><p><?=e($tagline)?><br>A home for thoughtful writing, notes, and perspectives.</p><a class="circle-link" href="#latest" aria-label="Read stories">↓</a></div><div class="hero-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-core">N<span>✳</span></div><div class="art-caption">MAKE ROOM<br>FOR THOUGHT.</div></div></section><section id="latest" class="latest wrap"><div class="section-head"><div><div class="eyebrow">THE JOURNAL</div><h2>Latest stories<span class="lime">.</span></h2></div><span class="count"><?=str_pad((string)count($posts),2,'0',STR_PAD_LEFT)?> STORIES</span></div><form class="public-search" method="get" action="<?=e(base_url('index.php'))?>"><input type="search" name="q" value="<?=e($search)?>" placeholder="Search stories…" aria-label="Search stories"><?php if($categorySlug!==''):?><input type="hidden" name="category" value="<?=e($categorySlug)?>"><?php endif;?><button type="submit">Search ↗</button><?php if($search!==''||$categorySlug!==''):?><a href="<?=e(base_url('index.php#latest'))?>">Clear</a><?php endif;?></form><?php if($categories):?><div id="topics" class="public-categories"><a class="topic-pill <?=$categorySlug===''?'selected':''?>" href="<?=e(base_url('index.php#latest'))?>">All stories</a><?php foreach($categories as $cat):?><a class="topic-pill <?=$categorySlug===$cat['slug']?'selected':''?>" href="<?=e(base_url('index.php?category='.rawurlencode($cat['slug']).'#latest'))?>"><?=e($cat['name'])?> <small><?= (int)$cat['post_count']?></small></a><?php endforeach;?></div><?php endif;?><?php if(!$posts): ?><div class="empty"><div class="empty-icon">✳</div><h3><?=($search!==''||$categorySlug!=='')?'No stories found.':'The first page is yours.'?></h3><p><?=($search!==''||$categorySlug!=='')?'Try a different search or clear the category filter.':'Published stories will appear here. Sign in to the studio to write your first post.'?></p></div><?php else: ?><div class="post-grid"><?php foreach($posts as $i=>$p): ?><a class="post-card <?= $i===0?'featured':'' ?>" href="<?=e(base_url('article.php?slug='.rawurlencode($p['slug'])))?>"><div class="post-image" <?php if($p['cover_image'] && valid_http_url($p['cover_image'])): ?>style="background-image:url('<?=e($p['cover_image'])?>')"<?php endif; ?>><span class="image-index"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><span class="image-arrow">↗</span><?php if(!$p['cover_image']): ?><span class="image-glyph">✳</span><?php endif; ?></div><div class="post-meta"><span><?=e(date('M d, Y',strtotime($p['published_at'] ?: $p['created_at'])))?></span><span>·</span><span><?=e($p['author_name'] ?: $siteName)?></span></div><?php if($p['category_names']):?><div class="card-category"><?=e($p['category_names'])?></div><?php endif;?><h3><?=e($p['title'])?></h3><p><?=e($p['excerpt'] ?: text_substr(strip_tags($p['content']),0,150).'…')?></p></a><?php endforeach; ?></div><?php endif; ?></section><?php if($pageBlocks): ?><section class="builder-sections wrap" aria-label="Featured sections"><?php foreach($pageBlocks as $block): if(!is_array($block)) continue; $bt=(string)($block['type']??'text'); $title=(string)($block['title']??''); $body=(string)($block['text']??''); $button=(string)($block['button']??''); $url=(string)($block['url']??''); $image=(string)($block['image']??''); if($title==='' && $body==='') continue; ?><article class="builder-section builder-<?=e(in_array($bt,['feature','text','image','cta'],true)?$bt:'text')?>"><?php if($image!=='' && (str_starts_with($image,'/') || preg_match('~^https?://~i',$image))): ?><img class="builder-section-image" src="<?=e($image)?>" alt="" loading="lazy" decoding="async"><?php endif; ?><div class="builder-section-copy"><?php if($title!==''): ?><h2><?=e($title)?></h2><?php endif; ?><?php if($body!==''): ?><p><?=nl2br(e($body))?></p><?php endif; ?><?php if($button!=='' && $url!=='' && (str_starts_with($url,'#') || str_starts_with($url,'/') || preg_match('~^https?://~i',$url))): ?><a class="builder-section-button" href="<?=e($url)?>"><?=e($button)?> ↗</a><?php endif; ?></div></article><?php endforeach; ?></section><?php endif; ?>
<section id="about" class="about wrap"><div class="eyebrow">A NOTE ON NOWRD</div><h2>Less noise.<br><em>More meaning.</em></h2><p>NOWRD is an independent publishing space for ideas that deserve a little more time. Built for writers, made for readers.</p><span class="about-star">✳</span></section></main><footer class="footer wrap"><a class="brand" href="#top"><span class="brand-mark"><?=e($brandMark)?></span> <?=e($siteName)?></a><span>© <?=date('Y')?> NOWRD Studio</span><span>Made for the curious <b>✳</b></span></footer><script>window.NOWRD_VISUAL = <?=json_encode(nowrd_visual_preferences(), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>; window.NOWRD_VISUAL_ADMIN = false;</script><script src="<?=e(base_url('public/assets/ui-v10.js'))?>" defer></script></body></html>
